import { createRequire } from 'node:module'
import { cp, copyFile, mkdtemp, realpath, rm } from 'node:fs/promises'
import { dirname, join, relative } from 'node:path'
import { tmpdir } from 'node:os'
import { appRoot, repositoryRoot } from '../../tools/lib/paths'
import { hostTarget } from '../../tools/lib/targets'
import { electronExecutable } from '../../tools/dev/electron-executable'
import { readPnpm, run } from '@kisaki3/tooling/process'

/** Copy the workspace for source-editing tests; close() removes the copy after its session stops. */
export async function prepareDevelopmentWorkspace(): Promise<{
  root: string
  app: string
  close(): Promise<void>
}> {
  const temporary = await mkdtemp(join(tmpdir(), 'kisaki-dev-workspace-'))
  try {
    // Resolve short paths before pnpm records dependency links and Vite resolves module locations.
    const root = await realpath(temporary)
    const app = join(root, 'clients', 'desktop', 'app')

    for (const file of [
      'package.json',
      'pnpm-workspace.yaml',
      'pnpm-lock.yaml',
      'turbo.json',
      'tsconfig.json',
      '.npmrc',
      '.prettierrc.json',
      '.gitignore',
      'eslint.config.ts',
    ]) {
      await copyFile(join(repositoryRoot, file), join(root, file))
    }
    await cp(join(repositoryRoot, 'config', 'typescript'), join(root, 'config', 'typescript'), {
      recursive: true,
    })

    const ignored = new Set([
      'node_modules',
      'out',
      'dist',
      '.cache',
      '.local',
      'target',
      '.vitest',
      '.turbo',
      'test-results',
      'playwright-report',
    ])
    for (const directory of ['clients', 'packages']) {
      await cp(join(repositoryRoot, directory), join(root, directory), {
        recursive: true,
        filter(path) {
          return !relative(join(repositoryRoot, directory), path)
            .split(/[\\/]/)
            .some((part) => ignored.has(part))
        },
      })
    }

    // Turbo needs a valid HEAD to keep generated outputs out of its default input set.
    await run('git', ['init', '--quiet'], { cwd: root })
    await run(
      'git',
      [
        '-c',
        'core.hooksPath=',
        '-c',
        'commit.gpgSign=false',
        '-c',
        'user.name=Fixture',
        '-c',
        'user.email=fixture@example.invalid',
        'commit',
        '--allow-empty',
        '--quiet',
        '-m',
        'Initialize development fixture',
      ],
      { cwd: root },
    )

    const store = await readPnpm(['store', 'path'], repositoryRoot)
    try {
      await readPnpm(
        [
          'install',
          '--store-dir',
          dirname(store.trim()),
          '--offline',
          '--ignore-scripts',
          '--frozen-lockfile',
        ],
        root,
      )
    } catch (cause) {
      const failure = cause as { stdout?: string; stderr?: string }
      throw new Error(
        `Fixture installation failed:\n${`${failure.stdout ?? ''}\n${failure.stderr ?? ''}`.slice(-8_192)}`,
        { cause },
      )
    }

    const originalRequire = createRequire(join(appRoot, 'package.json'))
    const fixtureRequire = createRequire(join(app, 'package.json'))
    const originalElectron = dirname(originalRequire.resolve('electron/package.json'))
    const fixtureElectron = dirname(fixtureRequire.resolve('electron/package.json'))
    // Electron installs its binary on first import; prepare it before copying the distribution.
    electronExecutable()
    if ((await realpath(originalElectron)) !== (await realpath(fixtureElectron))) {
      // macOS framework links must keep their relative targets inside the copied application bundle.
      await cp(join(originalElectron, 'dist'), join(fixtureElectron, 'dist'), {
        recursive: true,
        verbatimSymlinks: true,
      })
      await copyFile(join(originalElectron, 'path.txt'), join(fixtureElectron, 'path.txt'))
    }

    const target = hostTarget()
    // Cargo dependencies may be reused, but the copied crate and its target output remain isolated.
    await cp(join(appRoot, '.cache', 'native', target), join(app, '.cache', 'native', target), {
      recursive: true,
    })

    return {
      root,
      app,
      close: () => rm(root, { recursive: true, force: true, maxRetries: 5, retryDelay: 200 }),
    }
  } catch (cause) {
    await rm(temporary, { recursive: true, force: true, maxRetries: 5, retryDelay: 200 })
    throw cause
  }
}

import { _electron, expect, test } from '@playwright/test'
import { cpus, release, totalmem, tmpdir } from 'node:os'
import { mkdtemp, readFile, rm } from 'node:fs/promises'
import { join } from 'node:path'
import { performance } from 'node:perf_hooks'
import { electronExecutable } from '../../tools/dev/electron-executable'
import { buildDirectory } from '../../tools/lib/paths'
import { hostTarget } from '../../tools/lib/targets'
import { budgets } from './budgets'

test('measures twenty fresh processes and confirms all observed child processes exit', async ({}, info) => {
  const runtime = buildDirectory(hostTarget())
  const profile = await mkdtemp(join(tmpdir(), 'kisaki-performance-'))
  const samples: { milliseconds: number; workingSetKiB: number }[] = []
  try {
    for (let index = 0; index < budgets.samples; index++) {
      const env: Record<string, string> = Object.fromEntries(
        Object.entries(process.env).filter(
          (entry): entry is [string, string] => entry[1] !== undefined,
        ),
      )
      delete env.ELECTRON_RUN_AS_NODE

      const sample = `Sample ${index + 1}`
      const { application, start } = await test.step(`${sample}: launch`, async () => {
        const start = performance.now()
        const application = await _electron.launch({
          executablePath: electronExecutable(),
          args: [join(runtime, 'main/entry.js'), `--profile=${profile}`],
          env,
        })
        return { application, start }
      })

      let pids: number[] = []
      try {
        const milliseconds = await test.step(`${sample}: window ready`, async () => {
          const window = await application.firstWindow()
          await window.getByRole('button', { name: 'Close window' }).waitFor()
          return performance.now() - start
        })
        const metrics = await test.step(`${sample}: process metrics`, () =>
          application.evaluate(({ app }) =>
            app
              .getAppMetrics()
              .map(({ pid, memory }) => ({ pid, workingSetSize: memory.workingSetSize })),
          ))
        pids = metrics.map((metric) => metric.pid)
        samples.push({
          milliseconds,
          workingSetKiB: metrics.reduce((sum, metric) => sum + metric.workingSetSize, 0),
        })
      } finally {
        await test.step(`${sample}: close`, () => application.close())
      }

      await test.step(`${sample}: observed processes exit`, () =>
        expect
          .poll(
            () =>
              pids.filter((pid) => {
                try {
                  process.kill(pid, 0)
                  return true
                } catch {
                  return false
                }
              }),
            { timeout: 5_000 },
          )
          .toEqual([]))
    }

    const sorted = samples.map((sample) => sample.milliseconds).sort((a, b) => a - b)
    const p95 = sorted[Math.ceil(sorted.length * 0.95) - 1]!
    const mean = sorted.reduce((sum, value) => sum + value, 0) / sorted.length
    const middle = Math.floor(sorted.length / 2)
    const median =
      sorted.length % 2 === 0 ? (sorted[middle - 1]! + sorted[middle]!) / 2 : sorted[middle]!

    const report = {
      target: hostTarget(),
      osRelease: release(),
      cpu: cpus()[0]?.model,
      memoryBytes: totalmem(),
      mode: 'fresh processes, warm OS disk cache, isolated retained profile, W00 shell only',
      build: JSON.parse(await readFile(join(runtime, 'build.json'), 'utf8')),
      samples,
      medianMs: median,
      p95Ms: p95,
      maxMs: sorted.at(-1),
      standardDeviationMs: Math.sqrt(
        sorted.reduce((sum, value) => sum + (value - mean) ** 2, 0) / sorted.length,
      ),
    }
    await info.attach('startup.json', {
      body: JSON.stringify(report, null, 2),
      contentType: 'application/json',
    })
    expect(p95).toBeLessThanOrEqual(budgets.engineeringShellStartupP95Ms)
  } finally {
    await rm(profile, { recursive: true, force: true })
  }
})
